let flightLane = null;
if (name === 'floor-washtub') {
  // The stage-redesign fixture adds native walls around the original spawn
  // deck. Keep the real Explosher/Actor.update/Projectiles flight test, but
  // select an unobstructed heading from the actual muzzle instead of assuming
  // +Z is open forever. A short native ray probe chooses a path with enough
  // initial clearance for the required F5/F15 airborne captures; the later
  // production projectile must still retire on a real paintable floor face.
  const lanes = [];
  for (let index = 0; index < 32; index++) {
    const yaw = index * Math.PI * 2 / 32;
    // Rotate the real character first so the probe starts at that heading's
    // actual hand/muzzle transform, not the default +Z muzzle offset.
    a.yaw = yaw; a.aimYaw = yaw;
    a.character.root.rotation.y = yaw; a.character.root.updateMatrixWorld(true);
    G.scene.updateMatrixWorld(true);
    const muzzle = G.projectiles._muzzle(a, new V());
    const direction = new V(Math.sin(yaw), 0, Math.cos(yaw));
    const hit = { hit: false, point: new V(), normal: new V(), dist: 0, block: -1, face: -1, u: 0, v: 0 };
    const result = G.physics.raycast(muzzle, direction, 10, hit, true);
    const clearance = result?.hit === true ? result.dist : 10;
    lanes.push({ yaw, muzzle: muzzle.toArray(), direction: direction.toArray(), clearance,
      obstruction: result?.hit === true ? { block: result.block, face: result.face, point: result.point.toArray() } : null });
  }
  lanes.sort((left, right) => right.clearance - left.clearance || left.yaw - right.yaw);
  flightLane = lanes[0] ?? null;
  if (!flightLane || flightLane.clearance < 8) {
    throw new Error('No native Explosher flight lane has the required 8m initial clearance: ' + JSON.stringify(lanes));
  }
  a.yaw = flightLane.yaw; a.aimYaw = flightLane.yaw; a.aimPitch = 0;
  a.aimDir.set(...flightLane.direction);
  a.aimPoint.copy(a.pos).add(new V(flightLane.direction[0] * 24, 1.05, flightLane.direction[2] * 24));
  a.character.root.rotation.y = flightLane.yaw; a.character.root.updateMatrixWorld(true);
  G.scene.updateMatrixWorld(true);
}

const P = G.projectiles;
if(!P.__iwLifecycleTraceWashtub){
  const trace=window.__iwProjectileLifecycleTrace=[];
  const watch=p=>p?.wid==='s3-slosher-washtub'||p?.catalog?.r?.sourceActor==='WeaponSlosherBathtub';
  const state=p=>p?{seed:p.seed,wid:p.wid,age:p.age,life:p.life,delay:p.delay,pos:p.pos?.toArray?.(),vel:p.vel?.toArray?.(),catalog:!!p.catalog,travel:p.catalog?.travel,range:p.catalog?.range,descriptorLife:p.catalog?.descriptor?.life}:null;
  const originalStep=P._step;
  P._step=function(p,stepDt){
    const active=watch(p);if(active)trace.push({event:'step-enter',state:state(p),dt:stepDt});
    const result=originalStep.call(this,p,stepDt);
    if(active)trace.push({event:'step-exit',state:state(p),result});
    return result;
  };
  const originalUpdate=P.update;
  P.update=function(updateDt,...args){
    const before=this.list.filter(watch).map(state);trace.push({event:'update-enter',dt:updateDt,before});
    const result=originalUpdate.call(this,updateDt,...args);
    const after=this.list.filter(watch).map(state);trace.push({event:'update-exit',after});
    return result;
  };
  const list=P.list,originalPop=list.pop;
  list.pop=function(...args){
    const item=this[this.length-1];if(watch(item))trace.push({event:'list-pop',state:state(item),stack:new Error('Washtub list pop').stack});
    return originalPop.apply(this,args);
  };
  if(typeof P._recycle==='function'){
    const originalRecycle=P._recycle;
    P._recycle=function(p,...args){if(watch(p))trace.push({event:'recycle',state:state(p),stack:new Error('Washtub recycle').stack});return originalRecycle.call(this,p,...args);};
  }
  P.__iwLifecycleTraceWashtub=true;
}
const lifecycleTraceStart=window.__iwProjectileLifecycleTrace.length;

